1	#!/usr/bin/env node
2	/**
3	 * LunaCore â€” statusline / mini-dashboard for Claude Code.
4	 *
5	 * Standalone, zero-dependency, cross-platform. Reads the JSON Claude Code pipes
6	 * to a statusLine command on stdin and renders (matching the "LunaCore // dash"
7	 * design â€” dark mono, cyanâ†’magenta):
8	 *
9	 *   line 0  <model> â€˘ <ctx%> â€˘ <elapsed> â€˘ <mcp> â€˘ $<cost>     â”
10	 *   line 1  â—Ź <60 send it   â—Ź 60-85 compact maybe?  â—Ź >85 â€¦    â”‚  big "LunaCore"
11	 *   line 2  cheat â†’ Ctrl+]  Â·  LunaCore // dash                â”‚  block wordmark
12	 *   line 3  solo Â· lean Â· v1                                   â”‚  on the right
13	 *   line 4  (spacer)                                           â”
14	 *
15	 * The three context LEDs are a legend: the CURRENT zone is bright, the others
16	 * dimmed. Zones: green <60%, amber 60â€“85%, red >85% (the "compact this shit"
17	 * zone). It never shells out to a CLI â€” ctx% is computed from the transcript,
18	 * MCP count from local config.
19	 *
20	 * Env overrides:
21	 *   LUNA_SL_ART=0            hide the big LunaCore wordmark (compact mode)
22	 *   LUNA_SL_HIDE_COST=1      hide the cost segment
23	 *   LUNA_SL_COST_SYMBOL=$    change the cost symbol (e.g. âšˇ, â‚¬)
24	 *   LUNA_SL_CTX_LIMIT=200000 context window size used for the % (default 200000)
25	 *   LUNA_SL_CTX_WARN=60      amber threshold (default 60)
26	 *   LUNA_SL_CTX_DANGER=85    red / "compact this shit" threshold (default 85)
27	 *   LUNA_SL_CHEAT_URL=...    cheatsheet link shown on the hint line
28	 *   LUNA_SL_NOCOLOR=1        disable ANSI colors
29	 */
30	'use strict';
31	
32	const fs = require('fs');
33	const path = require('path');
34	const os = require('os');
35	const { execSync } = require('child_process');
36	
37	// â”€â”€ config â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
38	const CTX_LIMIT = Number(process.env.LUNA_SL_CTX_LIMIT || 200000);
39	const CTX_WARN = Number(process.env.LUNA_SL_CTX_WARN || 60);
40	const CTX_DANGER = Number(process.env.LUNA_SL_CTX_DANGER || 85);
41	const SHOW_ART = !/^(0|false|no|off)$/i.test(process.env.LUNA_SL_ART || '');
42	const CHEAT_URL =
43	  process.env.LUNA_SL_CHEAT_URL ||
44	  'https://claude.ai/code/artifact/f3981a16-0794-4fd7-8a62-fd1f2f08d4fa';
45	
46	// â”€â”€ ANSI helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
47	const NOCOLOR = /^(1|true|yes|on)$/i.test(process.env.LUNA_SL_NOCOLOR || '');
48	const c = (code, s) => (NOCOLOR ? s : `\x1b[${code}m${s}\x1b[0m`);
49	const cyan = (s) => c('96', s);    // Luna / model â€” bright cyan
50	const magenta = (s) => c('95', s); // Core / elapsed â€” bright magenta
51	const green = (s) => c('92', s);   // ctx ok / cost
52	const yellow = (s) => c('93', s);  // ctx warn
53	const red = (s) => c('91', s);     // ctx danger
54	const blue = (s) => c('94', s);    // mcp
55	const gray = (s) => c('90', s);    // separators / dimmed
56	const bold = (s) => c('1', s);
57	const sep = gray('  \u2022  ');
58	const stripAnsi = (s) => s.replace(/\x1b\[[0-9;]*m/g, '');
59	const padTo = (s, w) => s + ' '.repeat(Math.max(0, w - stripAnsi(s).length));
60	// Hard-truncate a possibly-ANSI-colored string to at most `maxVisible` visible
61	// chars, copying escape codes through uncounted. This is the safety net that
62	// guarantees a left-column line can never push the total printed width past
63	// the art's start column â€” which is what was wrapping the wordmark.
64	function truncateVisible(s, maxVisible) {
65	  if (maxVisible <= 0) return '';
66	  if (stripAnsi(s).length <= maxVisible) return s;
67	  let out = '';
68	  let visible = 0;
69	  for (let i = 0; i < s.length; i++) {
70	    if (s[i] === '\x1b') {
71	      const m = /^\x1b\[[0-9;]*m/.exec(s.slice(i));
72	      if (m) { out += m[0]; i += m[0].length - 1; continue; }
73	    }
74	    if (visible >= maxVisible - 1) { out += '\u2026'; visible++; break; }
75	    out += s[i];
76	    visible++;
77	  }
78	  return out + (NOCOLOR ? '' : '\x1b[0m');
79	}
80	// Real available terminal width. process.stdout.columns/COLUMNS are unset
81	// when Claude Code pipes our stdout (not a TTY), so on Windows fall back to
82	// querying the console device directly; otherwise use a conservative default
83	// rather than a generous one, since overshooting is what causes wrapping.
84	function getCols() {
85	  if (process.stdout.columns) return process.stdout.columns;
86	  const envCols = Number(process.env.COLUMNS);
87	  if (envCols > 0) return envCols;
88	  if (process.platform === 'win32') {
89	    try {
90	      const out = execSync('mode con', { timeout: 300, windowsHide: true }).toString();
91	      const m = /Columns:\s*(\d+)/i.exec(out);
92	      if (m) return Number(m[1]);
93	    } catch (_) { /* no console attached / mode unavailable */ }
94	  }
95	  return 80;
96	}
97	
98	// â”€â”€ read stdin JSON (best-effort) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
99	function readStdin() {
100	  try {
101	    const raw = fs.readFileSync(0, 'utf8');
102	    return raw ? JSON.parse(raw) : {};
103	  } catch (_) {
104	    return {};
105	  }
106	}
107	
108	// â”€â”€ ctx% from the session transcript â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
109	// Claude Code writes the session as JSONL at data.transcript_path. The last
110	// message carrying a usage block tells us how many tokens are currently in the
111	// context window. We tail the file so large sessions stay cheap. Returns 0 when
112	// the session is fresh (no usage yet) so the green LED still shows.
113	function contextPct(data) {
114	  const tp = data.transcript_path;
115	  try {
116	    if (!tp || !fs.existsSync(tp)) {
117	      if (data.exceeds_200k_tokens) return 100;
118	      return 0;
119	    }
120	    const stat = fs.statSync(tp);
121	    const readBytes = Math.min(stat.size, 262144); // last 256 KB
122	    const fd = fs.openSync(tp, 'r');
123	    const buf = Buffer.alloc(readBytes);
124	    fs.readSync(fd, buf, 0, readBytes, stat.size - readBytes);
125	    fs.closeSync(fd);
126	    const lines = buf.toString('utf8').split('\n').filter(Boolean);
127	    for (let i = lines.length - 1; i >= 0; i--) {
128	      let obj;
129	      try { obj = JSON.parse(lines[i]); } catch (_) { continue; }
130	      const u = (obj.message && obj.message.usage) || obj.usage;
131	      if (u && (u.input_tokens != null || u.cache_read_input_tokens != null)) {
132	        const used =
133	          (u.input_tokens || 0) +
134	          (u.cache_read_input_tokens || 0) +
135	          (u.cache_creation_input_tokens || 0);
136	        return Math.min(100, Math.round((used / CTX_LIMIT) * 100));
137	      }
138	    }
139	  } catch (_) { /* ignore */ }
140	  return 0;
141	}
142	
143	// â”€â”€ MCP status from local config â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
144	// Native stdin carries no live MCP handshake state, so we report the number of
145	// MCP servers actually wired up: user (~/.claude.json) + project (.mcp.json) +
146	// every ENABLED plugin's own .mcp.json (disabled plugins skipped, so a turned-
147	// off ruflo no longer counts). Deduped by name, cached 30s.
148	function readJSON(p) {
149	  try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; }
150	}
151	function mcpStatus() {
152	  const cacheFile = path.join(os.tmpdir(), 'luna-sl-mcp.json');
153	  try {
154	    const st = fs.statSync(cacheFile);
155	    if (Date.now() - st.mtimeMs < 30000) return readJSON(cacheFile).count;
156	  } catch (_) { /* stale/missing â†’ recompute */ }
157	
158	  const home = os.homedir();
159	  const names = new Set();
160	  const add = (o) => { if (o && typeof o === 'object') Object.keys(o).forEach((k) => names.add(k)); };
161	
162	  const uj = readJSON(path.join(home, '.claude.json'));
163	  if (uj) add(uj.mcpServers);
164	  const pj = readJSON(path.join(process.cwd(), '.mcp.json'));
165	  if (pj) add(pj.mcpServers);
166	
167	  const settings = readJSON(path.join(home, '.claude', 'settings.json')) || {};
168	  const enabled = settings.enabledPlugins || {};
169	  const installed = readJSON(path.join(home, '.claude', 'plugins', 'installed_plugins.json'));
170	  if (installed && installed.plugins) {
171	    for (const pname of Object.keys(installed.plugins)) {
172	      if (enabled[pname] === false) continue; // skip disabled plugins (e.g. ruflo)
173	      for (const inst of installed.plugins[pname]) {
174	        if (!inst || !inst.installPath) continue;
175	        const mj = readJSON(path.join(inst.installPath, '.mcp.json'));
176	        if (mj) add(mj.mcpServers);
177	      }
178	    }
179	  }
180	
181	  const count = names.size;
182	  try { fs.writeFileSync(cacheFile, JSON.stringify({ count, names: [...names] })); } catch (_) {}
183	  return count;
184	}
185	
186	// â”€â”€ formatting â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
187	function fmtDuration(ms) {
188	  if (!ms || ms < 0) return null;
189	  const s = Math.floor(ms / 1000);
190	  const h = Math.floor(s / 3600);
191	  const m = Math.floor((s % 3600) / 60);
192	  const sec = s % 60;
193	  if (h) return `${h}h${String(m).padStart(2, '0')}m`;
194	  if (m) return `${m}m${String(sec).padStart(2, '0')}s`;
195	  return `${sec}s`;
196	}
197	
198	function ctxZone(pct) {
199	  if (pct > CTX_DANGER) return 'r';
200	  if (pct >= CTX_WARN) return 'y';
201	  return 'g';
202	}
203	const ZONE_COLOR = { g: green, y: yellow, r: red };
204	
205	// -- right-aligned wordmark -----------------------------------------------
206	function gradientText(text) {
207	  const start = [90, 220, 230];
208	  const end = [215, 0, 190];
209	  const width = Math.max(1, text.length - 1);
210	  let out = '';
211	  for (let i = 0; i < text.length; i++) {
212	    const ch = text[i];
213	    const t = i / width;
214	    const r = Math.round(start[0] + (end[0] - start[0]) * t);
215	    const g = Math.round(start[1] + (end[1] - start[1]) * t);
216	    const b = Math.round(start[2] + (end[2] - start[2]) * t);
217	    out += NOCOLOR ? ch : `\x1b[1;38;2;${r};${g};${b}m${ch}`;
218	  }
219	  return out + (NOCOLOR ? '' : '\x1b[0m');
220	}
221	function wordmark() {
222	  return gradientText('LUNACORE');
223	}
224	
225	function main() {
226	  const data = readStdin();
227	
228	// â”€â”€ left column â”€â”€
229	  const model =
230	    (data.model && (data.model.display_name || data.model.id)) || 'claude';
231	  const pct = contextPct(data);
232	  const zone = ctxZone(pct);
233	  const dur = fmtDuration(data.cost && data.cost.total_duration_ms);
234	  const mcp = mcpStatus();
235	
236	  // line 0 â€” mini dashboard
237	  const d0 = [];
238	  d0.push(cyan(model));
239	  d0.push(ZONE_COLOR[zone](`\u25CF ${pct}% ctx`));
240	  if (dur) d0.push(magenta(dur));
241	  d0.push((mcp > 0 ? green('\u25CF') : gray('\u25CF')) + blue(` mcp ${mcp}`));
242	  const hideCost = /^(1|true|yes|on)$/i.test(process.env.LUNA_SL_HIDE_COST || '');
243	  if (!hideCost && data.cost && typeof data.cost.total_cost_usd === 'number') {
244	    const sym = process.env.LUNA_SL_COST_SYMBOL ?? '$';
245	    d0.push(green(`${sym}${data.cost.total_cost_usd.toFixed(2)}`));
246	  }
247	  const line0 = d0.join(sep);
248	
249	  // line 1 â€” context LED legend (current zone bright, others dimmed).
250	  // Two label sets: full text when there's room next to the art, a compact
251	  // one when the panel is narrow â€” chosen once we know the real budget below.
252	  const led = (z, label, color) => {
253	    const txt = z === zone ? bold(color(label)) : gray(label);
254	    return (z === zone ? color('\u25CF') : gray('\u25CF')) + ' ' + txt;
255	  };
256	  const buildLine1 = (labels) =>
257	    led('g', labels.g, green) + '   ' +
258	    led('y', labels.y, yellow) + '   ' +
259	    led('r', labels.r, red);
260	  const LEGEND_FULL = {
261	    g: `<${CTX_WARN} send it`,
262	    y: `${CTX_WARN}-${CTX_DANGER} compact maybe?`,
263	    r: `>${CTX_DANGER} compact this shit`,
264	  };
265	  const LEGEND_COMPACT = {
266	    g: `<${CTX_WARN} ok`,
267	    y: `${CTX_WARN}-${CTX_DANGER}`,
268	    r: `>${CTX_DANGER} !!`,
269	  };
270	
271	  // line 2 - cheatsheet hint. Ctrl+] is the shortcut; the path is shown as a fallback.
272	  const line2 = gray('cheat ') + cyan('Ctrl+]') + gray(' \u2192 ') + cyan('~/.claude/helpers/ecc-sciagawka-mati.html');
273	
274	  const cols = Math.max(1, getCols() - 1);
275	  const mark = SHOW_ART ? wordmark() : '';
276	  const markW = stripAnsi(mark).length;
277	  const MARGIN = markW ? 2 : 0;
278	  const LEFTW = markW ? Math.max(16, cols - markW - MARGIN) : cols;
279	
280	  const line1Full = buildLine1(LEGEND_FULL);
281	  const line1 = stripAnsi(line1Full).length <= LEFTW ? line1Full : buildLine1(LEGEND_COMPACT);
282	  const rowsLeft = [line0, line1, line2].map((s) => truncateVisible(s, LEFTW));
283	
284	  if (!mark || cols - markW - MARGIN < 16) {
285	    process.stdout.write(rowsLeft.join('\n'));
286	    return;
287	  }
288	
289	  const gap = ' '.repeat(MARGIN);
290	  const out = rowsLeft.map((line, i) => {
291	    if (i !== 0) return line;
292	    return padTo(line, LEFTW) + gap + mark;
293	  });
294	  process.stdout.write(out.join('\n'));
295	}
296	
297	main();
298

