input.old_string:
// Real available terminal width. process.stdout.columns/COLUMNS are unset
// when Claude Code pipes our stdout (not a TTY), so on Windows fall back to
// querying the console device directly; otherwise use a conservative default
// rather than a generous one, since overshooting is what causes wrapping.
function getCols() {
  if (process.stdout.columns) return process.stdout.columns;
  const envCols = Number(process.env.COLUMNS);
  if (envCols > 0) return envCols;
  if (process.platform === 'win32') {
    try {
      const out = execSync('mode con', { timeout: 300, windowsHide: true }).toString();
      const m = /Columns:\s*(\d+)/i.exec(out);
      if (m) return Number(m[1]);
    } catch (_) { /* no console attached / mode unavailable */ }
  }
  return 80;
}

