    led('g', labels.g, green) + '   ' +
    led('y', labels.y, yellow) + '   ' +
    led('r', labels.r, red);
  const LEGEND_FULL = {
    g: `<${CTX_WARN} send it`,
    y: `${CTX_WARN}-${CTX_DANGER} compact maybe?`,
    r: `>${CTX_DANGER} compact this shit`,
  };
  const LEGEND_COMPACT = {
    g: `<${CTX_WARN} ok`,
    y: `${CTX_WARN}-${CTX_DANGER}`,
    r: `>${CTX_DANGER} !!`,
  };

  // line 2 - cheatsheet hint. Ctrl+] is the shortcut; the path is shown as a fallback.
  const line2 = gray('cheat ') + cyan('Ctrl+]') + gray(' \u2192 ') + cyan('~/.claude/helpers/ecc-sciagawka-mati.html');

  const cols = Math.max(1, getCols() - 1);
  const mark = SHOW_ART ? wordmark() : '';
  const markW = stripAnsi(mark).length;
  const MARGIN = markW ? 2 : 0;
  const LEFTW = markW ? Math.max(16, cols - markW - MARGIN) : cols;

  const line1Full = buildLine1(LEGEND_FULL);
  const line1 = stripAnsi(line1Full).length <= LEFTW ? line1Full : buildLine1(LEGEND_COMPACT);
  const rowsLeft = [line0, line1, line2].map((s) => truncateVisible(s, LEFTW));

