    process.stdout.write(rowsLeft.join('\n'));
    return;
  }

  const gap = ' '.repeat(MARGIN);
  const out = rowsLeft.map((line, i) => {
    if (i !== 0) return line;
    return padTo(line, LEFTW) + gap + mark;
  });
  process.stdout.write(out.join('\n'));
}

main();
