const CTX_LIMIT = Number(process.env.LUNA_SL_CTX_LIMIT || 200000);
const CTX_WARN = Number(process.env.LUNA_SL_CTX_WARN || 60);
const CTX_DANGER = Number(process.env.LUNA_SL_CTX_DANGER || 85);
