const magenta = (s) => c('95', s); // Core / elapsed â€” bright magenta
const green = (s) => c('92', s);   // ctx ok / cost
const yellow = (s) => c('93', s);  // ctx warn
const red = (s) => c('91', s);     // ctx danger
const blue = (s) => c('94', s);    // mcp
