  // detect file:// URIs and let you ctrl+click straight through to the
  // browser, so the URI itself IS the shortcut - no keybinding needed.
  const line2 = gray('cheat \u2192 ctrl+click ') + cyan(CHEAT_URL);

  const cols = Math.max(1, getCols() - 1);
  const mark = SHOW_ART ? wordmark() : '';
  const markW = stripAnsi(mark).length;
